import{_ as t,o,c as r,a3 as i}from"./chunks/framework.DQHjryjb.js";const g=JSON.parse('{"title":"Removing IsTemporal()","description":"","frontmatter":{"order":40,"sidebarTitle":"Removing IsTemporal()"},"headers":[],"relativePath":"migrations/removing-temporal.md","filePath":"migrations/removing-temporal.md"}'),a={name:"migrations/removing-temporal.md"};function n(s,e,l,h,d,m){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="removing-istemporal" tabindex="-1">Removing <code>IsTemporal()</code> <a class="header-anchor" href="#removing-istemporal" aria-label="Permalink to &quot;Removing `IsTemporal()`&quot;">​</a></h1><p>Remove the <code>IsTemporal()</code> call from an entity, or remove the entity from the model altogether, and the migration <strong>keeps the history table</strong>, columns, data and indexes included. The same rule as for a <a href="/hindsight-efcore/1.3/migrations/schema-evolution#removing-a-property">removed property</a> applies one level up: the table stays in the model, tagged <code>Hindsight:Orphaned</code>, so no generated migration ever drops it.</p><ul><li>If the entity is still mapped, its main table keeps evolving normally. Only the history table is pinned as it was.</li><li>The history table is kept for its data, not for queries. <code>AsOf</code>, <code>AllVersions</code> and <code>History&lt;T&gt;</code> require a temporal entity, so they throw <code>InvalidOperationException</code> for this one. Query the table with SQL if you need to.</li><li>Once orphaned, it stays in every later model, so nothing has to rediscover it.</li></ul><h2 id="with-the-trigger-writer" tabindex="-1">With the trigger writer <a class="header-anchor" href="#with-the-trigger-writer" aria-label="Permalink to &quot;With the trigger writer&quot;">​</a></h2><p>This is the one case where a generated migration drops something on its own. The trigger lives on the <em>main</em> table and would otherwise keep writing into a history table the model no longer considers temporal. So the migration that removes <code>IsTemporal()</code> runs <code>DROP FUNCTION … CASCADE</code>, which also drops the trigger. No data is deleted; only the writing stops. This happens once, in that migration.</p><h2 id="dropping-the-history-table" tabindex="-1">Dropping the history table <a class="header-anchor" href="#dropping-the-history-table" aria-label="Permalink to &quot;Dropping the history table&quot;">​</a></h2><p>If you really want the history table gone, write a migration that drops it yourself. Hindsight never will.</p>',7)])])}const c=t(a,[["render",n]]);export{g as __pageData,c as default};
